async(page)=>{await page.goto('http://127.0.0.1:43235/fcs/craft/cutting/replacement-fabric-fei-tickets');await page.waitForSelector('[data-hpb-action=detail]');return await page.evaluate(async()=>{const s=await import('/src/data/fcs/cutting/replacement-fabric-source.ts');const t=await import('/src/data/fcs/runtime-process-tasks.ts');return {rows:s.listReplacementFabricOrderRows().map(x=>({id:x.order.productionOrderId,materials:x.materials,issues:x.issues})),tasks:t.listRuntimeProcessTasks().filter(x=>x.productionOrderId==='PO-202603-0002'&&x.processCode==='CUT_PANEL').map(x=>({id:x.taskId,bom:x.consumedBomItemIds,factory:x.assignedFactoryId}))}})}
